struct Error: std::runtime_error { using std::runtime_error::runtime_error; };
struct Env; struct Stmt; struct Expr; struct Function; struct Interpreter; struct NativeFn;
using Value = std::variant<std::monostate,double,bool,std::string,std::shared_ptr<Function>,std::shared_ptr<NativeFn>>;
struct NativeFn{std::function<Value(const std::vector<Value>&)> fn; NativeFn(std::function<Value(const std::vector<Value>&)> f):fn(std::move(f)){} };
static std::string vstr(const Value& v){
  if(std::holds_alternative<std::monostate>(v)) return "null";
  if(auto p=std::get_if<double>(&v)){ std::ostringstream o; if(std::floor(*p)==*p) o<<(long long)*p; else o<<*p; return o.str(); }
  if(auto p=std::get_if<bool>(&v)) return *p?"true":"false";
  if(auto p=std::get_if<std::string>(&v)) return *p;
  if(std::holds_alternative<std::shared_ptr<Function>>(v)) return "<func>";
  if(std::holds_alternative<std::shared_ptr<NativeFn>>(v)) return "<native>";
  return "<?>";
}
static bool truthy(const Value& v){ if(std::holds_alternative<std::monostate>(v)) return false; if(auto p=std::get_if<bool>(&v)) return *p; if(auto p=std::get_if<double>(&v)) return *p!=0; if(auto p=std::get_if<std::string>(&v)) return !p->empty(); return true; }
static double num(const Value& v){ if(auto p=std::get_if<double>(&v)) return *p; if(auto p=std::get_if<bool>(&v)) return *p?1:0; throw Error("expected number, got "+vstr(v)); }

struct Token{std::string k; Value v; int line,col;};
struct Lexer{std::string s; size_t i=0; int line=1,col=1; Lexer(std::string x):s(std::move(x)){} char peek(int n=0){size_t j=i+n; return j<s.size()?s[j]:'\0';} char adv(){char c=peek(); i++; if(c=='\n'){line++;col=1;}else col++; return c;} void skip(){for(;;){while(std::isspace((unsigned char)peek())) adv(); if(peek()=='/'&&peek(1)=='/'){while(peek()!='\n'&&peek()!='\0') adv(); continue;} if(peek()=='/'&&peek(1)=='*'){adv();adv(); while(!(peek()=='*'&&peek(1)=='/')){ if(peek()=='\0') throw Error("unterminated comment"); adv(); } adv();adv(); continue;} break;}} std::vector<Token> toks(){std::vector<Token> out; std::string two[]={"==","!=","<=",">=","&&","||"}; std::string one="+-*/%(){};,=!<>,"; for(;;){skip(); int l=line,c=col; char ch=peek(); if(!ch){out.push_back({"EOF",{},l,c}); return out;} if(std::isalpha((unsigned char)ch)||ch=='_'){std::string t; while(std::isalnum((unsigned char)peek())||peek()=='_') t+=adv(); static std::vector<std::string> kw={"let","func","return","if","else","while","true","false","null"}; out.push_back({std::find(kw.begin(),kw.end(),t)!=kw.end()?t:"IDENT",t,l,c}); continue;} if(std::isdigit((unsigned char)ch)){std::string t; while(std::isdigit((unsigned char)peek())) t+=adv(); if(peek()=='.'){t+=adv(); while(std::isdigit((unsigned char)peek())) t+=adv();} out.push_back({"NUMBER",std::stod(t),l,c}); continue;} if(ch=='\"'){adv(); std::string t; while(peek()!='\"'){ if(peek()=='\0') throw Error("unterminated string"); if(peek()=='\\'){adv(); char e=adv(); t += e=='n'?'\n':e=='t'?'\t':e=='r'?'\r':e;} else t+=adv(); } adv(); out.push_back({"STRING",t,l,c}); continue;} std::string tw; tw+=ch; tw+=peek(1); bool ok=false; for(auto& x:two) if(tw==x){adv();adv(); out.push_back({x,x,l,c}); ok=true; break;} if(ok) continue; if(one.find(ch)!=std::string::npos){adv(); std::string k(1,ch); out.push_back({k,k,l,c}); continue;} throw Error("unexpected character at "+std::to_string(l)+":"+std::to_string(c)); }} };

struct Expr{virtual ~Expr()=default;}; using E=std::shared_ptr<Expr>; struct Lit:Expr{Value v; Lit(Value x):v(std::move(x)){} }; struct Var:Expr{std::string n; Var(std::string x):n(std::move(x)){} }; struct Unary:Expr{std::string op; E r; Unary(std::string o,E e):op(std::move(o)),r(e){} }; struct Bin:Expr{E l,r; std::string op; Bin(E a,std::string o,E b):l(a),r(b),op(std::move(o)){} }; struct Call:Expr{E c; std::vector<E>a; Call(E x,std::vector<E> y):c(x),a(std::move(y)){} };
struct Stmt{virtual ~Stmt()=default;}; using S=std::shared_ptr<Stmt>; struct Let:Stmt{std::string n; E e; Let(std::string x,E y):n(std::move(x)),e(y){} }; struct Assign:Stmt{std::string n; E e; Assign(std::string x,E y):n(std::move(x)),e(y){} }; struct ExprS:Stmt{E e; ExprS(E x):e(x){} }; struct Block:Stmt{std::vector<S>b; Block(std::vector<S>x):b(std::move(x)){} }; struct IfS:Stmt{E c; S t,o; IfS(E a,S b,S d):c(a),t(b),o(d){} }; struct WhileS:Stmt{E c; S b; WhileS(E a,S x):c(a),b(x){} }; struct FuncS:Stmt{std::string n; std::vector<std::string>p; std::shared_ptr<Block>b; FuncS(std::string x,std::vector<std::string> y,std::shared_ptr<Block> z):n(std::move(x)),p(std::move(y)),b(z){} }; struct Ret:Stmt{E e; Ret(E x):e(x){} };

struct Parser{std::vector<Token> t; size_t i=0; Parser(std::vector<Token>x):t(std::move(x)){} Token& cur(){return t[i];} bool match(const std::string& k){if(cur().k==k){i++; return true;} return false;} Token need(const std::string& k){if(!match(k)) throw Error("expected "+k+" at "+std::to_string(cur().line)+":"+std::to_string(cur().col)); return t[i-1];} std::vector<S> parse(){std::vector<S>b; while(cur().k!="EOF") b.push_back(decl()); return b;} S decl(){if(match("func")) return func(); if(match("let")) return let(); return stmt();} S func(){auto name=std::get<std::string>(need("IDENT").v); need("("); std::vector<std::string> p; if(!match(")")){do{p.push_back(std::get<std::string>(need("IDENT").v));}while(match(",")); need(")");} return std::make_shared<FuncS>(name,p,std::dynamic_pointer_cast<Block>(block()));} S let(){auto n=std::get<std::string>(need("IDENT").v); need("="); auto e=expr(); need(";"); return std::make_shared<Let>(n,e);} S stmt(){if(match("if")){need("("); auto c=expr(); need(")"); auto th=stmt(); S el=nullptr; if(match("else")) el=stmt(); return std::make_shared<IfS>(c,th,el);} if(match("while")){need("("); auto c=expr(); need(")"); return std::make_shared<WhileS>(c,stmt());} if(match("return")){E e=cur().k==";"?std::make_shared<Lit>(Value{}):expr(); need(";"); return std::make_shared<Ret>(e);} if(cur().k=="{") return block(); auto e=expr(); if(auto v=std::dynamic_pointer_cast<Var>(e); v && match("=")){auto val=expr(); need(";"); return std::make_shared<Assign>(v->n,val);} need(";"); return std::make_shared<ExprS>(e);} S block(){need("{"); std::vector<S>b; while(cur().k!="}") b.push_back(decl()); need("}"); return std::make_shared<Block>(b);} E expr(){return orx();} E orx(){auto n=andx(); while(match("||")) n=std::make_shared<Bin>(n,"||",andx()); return n;} E andx(){auto n=eq(); while(match("&&")) n=std::make_shared<Bin>(n,"&&",eq()); return n;} E eq(){auto n=cmp(); while(cur().k=="=="||cur().k=="!="){auto o=cur().k; i++; n=std::make_shared<Bin>(n,o,cmp());} return n;} E cmp(){auto n=term(); while(cur().k=="<"||cur().k=="<="||cur().k==">"||cur().k==">="){auto o=cur().k; i++; n=std::make_shared<Bin>(n,o,term());} return n;} E term(){auto n=factor(); while(cur().k=="+"||cur().k=="-"){auto o=cur().k; i++; n=std::make_shared<Bin>(n,o,factor());} return n;} E factor(){auto n=unary(); while(cur().k=="*"||cur().k=="/"||cur().k=="%"){auto o=cur().k; i++; n=std::make_shared<Bin>(n,o,unary());} return n;} E unary(){if(cur().k=="!"||cur().k=="-"){auto o=cur().k; i++; return std::make_shared<Unary>(o,unary());} return call();} E call(){auto n=primary(); while(match("(")){std::vector<E>a; if(!match(")")){do{a.push_back(expr());}while(match(",")); need(")");} n=std::make_shared<Call>(n,a);} return n;} E primary(){auto tok=cur(); if(match("NUMBER")||match("STRING")) return std::make_shared<Lit>(tok.v); if(match("true")) return std::make_shared<Lit>(true); if(match("false")) return std::make_shared<Lit>(false); if(match("null")) return std::make_shared<Lit>(Value{}); if(match("IDENT")) return std::make_shared<Var>(std::get<std::string>(tok.v)); if(match("(")){auto e=expr(); need(")"); return e;} throw Error("expected expression at "+std::to_string(tok.line)+":"+std::to_string(tok.col));}};

struct Env: std::enable_shared_from_this<Env>{std::shared_ptr<Env> parent; std::unordered_map<std::string,Value> m; Env(std::shared_ptr<Env>p=nullptr):parent(p){} void def(const std::string&n,Value v){m[n]=v;} Value get(const std::string&n){if(m.count(n))return m[n]; if(parent)return parent->get(n); throw Error("undefined name: "+n);} void set(const std::string&n,Value v){if(m.count(n)){m[n]=v;return;} if(parent){parent->set(n,v);return;} throw Error("undefined name: "+n);}};
struct ReturnX{Value v;};
struct Function{Interpreter* interp; std::string name; std::vector<std::string>p; std::shared_ptr<Block>b; std::shared_ptr<Env> closure; Value operator()(const std::vector<Value>&args);};
struct Interpreter{std::shared_ptr<Env> g=std::make_shared<Env>(); std::string base="."; std::vector<void*> libs; Interpreter(std::string b):base(std::move(b)){builtins();} ~Interpreter(){for(void* h:libs) if(h) dlclose(h);} std::string path(const std::string&p){return (!p.empty()&&p[0]=='/')?p:base+"/"+p;} void add(const std::string&n,std::function<Value(const std::vector<Value>&)>f){g->def(n,std::make_shared<NativeFn>(std::move(f)));} void builtins(){add("print",[](auto&a){for(size_t i=0;i<a.size();++i){if(i)std::cout<<" "; std::cout<<vstr(a[i]);} std::cout<<"\n"; return Value{};}); add("clock",[](auto&){return (double)std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count()/1000.0;}); add("len",[](auto&a){if(a.size()!=1) throw Error("len expects 1 arg"); if(auto s=std::get_if<std::string>(&a[0])) return (double)s->size(); throw Error("len expects string");}); add("str",[](auto&a){return vstr(a.at(0));}); add("int",[](auto&a){return (double)(long long)num(a.at(0));}); add("float",[](auto&a){return num(a.at(0));}); add("native",[this](auto&a){return native(a);}); add("plugin",[this](auto&a){if(a.size()!=1)throw Error("plugin(path) expects 1 arg"); auto p=std::get_if<std::string>(&a[0]); if(!p)throw Error("plugin path must be string"); void* h=dlopen(path(*p).c_str(),RTLD_NOW); if(!h) throw Error(dlerror()); using Reg=void(*)(Interpreter*); auto reg=(Reg)dlsym(h,"si_register"); if(!reg) throw Error("plugin must export: extern C void si_register(Interpreter*)"); libs.push_back(h); reg(this); return Value{};});} Value native(const std::vector<Value>&a){if(a.size()<4) throw Error("native(path, symbol, name, return_type, arg_type...) expected"); std::string libp=std::get<std::string>(a[0]), sym=std::get<std::string>(a[1]), name=std::get<std::string>(a[2]), ret=std::get<std::string>(a[3]); std::vector<std::string> types; for(size_t i=4;i<a.size();++i) types.push_back(std::get<std::string>(a[i])); void*h=dlopen(path(libp).c_str(),RTLD_NOW); if(!h) throw Error(dlerror()); void*fp=dlsym(h,sym.c_str()); if(!fp) throw Error(dlerror()); libs.push_back(h); if(ret=="double"&&types.size()==2&&types[0]=="double"&&types[1]=="double"){using F=double(*)(double,double); F f=(F)fp; add(name,[f,name](auto&x){if(x.size()!=2) throw Error(name+" expects 2 args"); return f(num(x[0]),num(x[1]));});} else if(ret=="int"&&types.size()==2&&types[0]=="int"&&types[1]=="int"){using F=int(*)(int,int); F f=(F)fp; add(name,[f,name](auto&x){if(x.size()!=2) throw Error(name+" expects 2 args"); return (double)f((int)num(x[0]),(int)num(x[1]));});} else throw Error("this tiny native binder currently supports double(double,double) and int(int,int)"); return Value{};} void run(const std::vector<S>&s){for(auto&x:s) exec(x,g);} void execBlock(const std::vector<S>&s,std::shared_ptr<Env>e){for(auto&x:s) exec(x,e);} void exec(S s,std::shared_ptr<Env>e){if(auto n=std::dynamic_pointer_cast<Let>(s)){e->def(n->n,eval(n->e,e));return;} if(auto n=std::dynamic_pointer_cast<Assign>(s)){e->set(n->n,eval(n->e,e));return;} if(auto n=std::dynamic_pointer_cast<ExprS>(s)){eval(n->e,e);return;} if(auto n=std::dynamic_pointer_cast<Block>(s)){execBlock(n->b,std::make_shared<Env>(e));return;} if(auto n=std::dynamic_pointer_cast<IfS>(s)){if(truthy(eval(n->c,e)))exec(n->t,e); else if(n->o)exec(n->o,e); return;} if(auto n=std::dynamic_pointer_cast<WhileS>(s)){while(truthy(eval(n->c,e)))exec(n->b,e);return;} if(auto n=std::dynamic_pointer_cast<FuncS>(s)){auto f=std::make_shared<Function>(); f->interp=this; f->name=n->n; f->p=n->p; f->b=n->b; f->closure=e; e->def(n->n,f);return;} if(auto n=std::dynamic_pointer_cast<Ret>(s)) throw ReturnX{eval(n->e,e)}; throw Error("unknown statement");} Value eval(E x,std::shared_ptr<Env>e){if(auto n=std::dynamic_pointer_cast<Lit>(x))return n->v; if(auto n=std::dynamic_pointer_cast<Var>(x))return e->get(n->n); if(auto n=std::dynamic_pointer_cast<Unary>(x)){auto r=eval(n->r,e); return n->op=="-"?Value(-num(r)):Value(!truthy(r));} if(auto n=std::dynamic_pointer_cast<Bin>(x)){ if(n->op=="&&") return truthy(eval(n->l,e))&&truthy(eval(n->r,e)); if(n->op=="||") return truthy(eval(n->l,e))||truthy(eval(n->r,e)); auto l=eval(n->l,e), r=eval(n->r,e); if(n->op=="+"){if(std::holds_alternative<std::string>(l)||std::holds_alternative<std::string>(r)) return vstr(l)+vstr(r); return num(l)+num(r);} if(n->op=="-")return num(l)-num(r); if(n->op=="*")return num(l)*num(r); if(n->op=="/")return num(l)/num(r); if(n->op=="%")return std::fmod(num(l),num(r)); if(n->op=="==")return vstr(l)==vstr(r); if(n->op=="!=")return vstr(l)!=vstr(r); if(n->op=="<")return num(l)<num(r); if(n->op=="<=")return num(l)<=num(r); if(n->op==">")return num(l)>num(r); if(n->op==">=")return num(l)>=num(r);} if(auto n=std::dynamic_pointer_cast<Call>(x)){auto fn=eval(n->c,e); std::vector<Value>a; for(auto&z:n->a)a.push_back(eval(z,e)); if(auto f=std::get_if<std::shared_ptr<NativeFn>>(&fn)) return (*f)->fn(a); if(auto sf=std::get_if<std::shared_ptr<Function>>(&fn)) return (**sf)(a); throw Error("not callable: "+vstr(fn));} throw Error("unknown expression");}};
Value Function::operator()(const std::vector<Value>&args){if(args.size()!=p.size()) throw Error(name+" expected "+std::to_string(p.size())+" args"); auto e=std::make_shared<Env>(closure); for(size_t i=0;i<p.size();++i)e->def(p[i],args[i]); try{interp->execBlock(b->b,e);}catch(ReturnX&r){return r.v;} return Value{};}
static std::string dirname(const std::string& f){auto p=f.find_last_of("/"); return p==std::string::npos?".":f.substr(0,p);} int main(int argc,char**argv){try{std::string src, file="<stdin>"; if(argc>1){file=argv[1]; std::ifstream in(file); if(!in) throw Error("cannot open "+file); std::ostringstream ss; ss<<in.rdbuf(); src=ss.str();} else {std::ostringstream ss; ss<<std::cin.rdbuf(); src=ss.str();} auto ast=Parser(Lexer(src).toks()).parse(); Interpreter(dirname(file)).run(ast); return 0;}catch(std::exception&e){std::cerr<<"si error: "<<e.what()<<"\n"; return 1;}}
